py-easy-46.syntax:
# General form
for item in iterable:
    if condition(item):
        break          # exits loop; else block is SKIPPED
else:
    # runs only if the loop ended without hitting break
    # (iterable exhausted, including when it was empty)
    ...

# Example: search for a prime factor
n = 49
for d in range(2, n):
    if n % d == 0:
        print('factor found:', d)
        break
else:
    print(n, 'is prime')

# Example: empty iterable still runs else
for x in []:
    pass
else:
    print('no items, else still runs')

# while loops support else too
tries = 0
while tries < 3:
    tries += 1
else:
    print('condition became false')

# Gotchas:
# - 'continue' does NOT skip else; only break does.
# - return or an uncaught exception inside the loop also skips else.
# - Think of it as 'no break' rather than 'otherwise'.
# - try/except/else is a different construct: its else runs when no exception occurred.

py-easy-62.syntax:
# General form: set operators (operands must both be sets/frozensets)
# a | b   union         -> elements in a OR b
# a & b   intersection  -> elements in BOTH a and b
# a - b   difference    -> elements in a but NOT in b
# a ^ b   symmetric diff -> elements in exactly ONE of a, b

evens = {0, 2, 4, 6}
small = {0, 1, 2, 3}

evens & small    # {0, 2}
evens | small    # {0, 1, 2, 3, 4, 6}
evens - small    # {4, 6}
evens ^ small    # {1, 3, 4, 6}

# Method forms accept any iterable, not just sets:
evens.intersection([2, 6, 8])   # {2, 6}
evens.union('ab')                # {0, 2, 4, 6, 'a', 'b'}
# {0, 2} & [2]  -> TypeError (operators need set operands)

# In-place variants mutate the left set:
# a &= b, a |= b, a -= b, a ^= b
# a.intersection_update(b), a.update(b), ...

# Gotchas:
# - Sets are unordered; printed order is not guaranteed.
# - {} is an empty dict, not a set; use set().
# - Result of empty intersection is set(), not {}.
# - frozenset & set -> frozenset (type of left operand).
